mapper.select:
/* 공통팀 유민상 isry.itgcms.itgBrd.mapper.ItgQnaBrdMapper.selectItgQnaBrdList 공통팀 유민상 */
SELECT A.UNITY_BBSCTT_ESNTAL_NO , A.UNITY_BBSCTT_TYPE_SE_CD , A.UNITY_BBSCTT_TYPE_SN , A.UNITY_BBSCTT_CTGRYB_SE_CD , A.IMPRTN_NTC_YN , A.OGDP_INST_NO , A.OGDP_DEPT_CD , A.UNITY_BBSCTT_TTL_NM , A.RLS_YN , A.ATFINO , (SELECT COUNT(MNG_SN) FROM SAB821 WHERE ATFINO = A.ATFINO AND FILE_STTS_SE_CD != 'D' AND ATCMFL_CL_NM = '0') AS ATFI_CNT , DEC_B64(SA_FN_GET_NAME(A.FRST_RGTR_ID)) AS FRST_RGTR_NM , A.FRST_RGTR_ID , TO_CHAR(A.FRST_REG_DT, 'YYYYMMDD') AS FRST_REG_DT , (SELECT COUNT(*) FROM SBA131 C WHERE NVL(C.DEL_YN, 'N') != 'Y' AND C.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO) AS CMNT_CNT , DEC_B64(SA_FN_GET_NAME(B.FRST_RGTR_ID)) AS CMNT_RGTR_NM , CASE WHEN TRUNC(SYSDATE - A.FRST_REG_DT) > 1 THEN 'N' ELSE 'Y' END AS NEW_BBSCTT , CASE A.CLLR_REG_YN WHEN 'Y' THEN '등록' ELSE '-' END AS CLLR_REG_YN , NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TASKWK_PRCS_SE_CD' AND CMMNS_CD_VALUE = B.TASKWK_PRCS_SE_CD),'신규') AS TASKWK_PRCS_SE_CD , NVL((SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'TASKWK_TASKFO_SE_CD' AND CMMNS_CD_VALUE = B.TASKWK_TASKFO_SE_CD),'-') AS TASKWK_TASKFO_SE_CD FROM SBA130 A LEFT JOIN ( SELECT SBA131.* , ROW_NUMBER() OVER(PARTITION BY UNITY_BBSCTT_ESNTAL_NO ORDER BY FRST_REG_DT DESC) AS ROW_NUMBER FROM SBA131 WHERE DEL_YN != 'Y' ) B ON B.ROW_NUMBER = 1 AND B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO WHERE 1=1 AND NVL(A.DEL_YN, 'N') != 'Y' AND A.UNITY_BBSCTT_TYPE_SE_CD = #{UNITY_BBSCTT_TYPE_SE_CD}
AND #{strUNT_TASKWK_SE_CD} IN ( SELECT B.UNT_TASKWK_SE_CD FROM SBA132 B WHERE B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO )
AND A.UNITY_BBSCTT_CTGRYB_SE_CD = #{UNITY_BBSCTT_CTGRYB_SE_CD}
AND A.UNITY_BBSCTT_CTGRYB_SE_CD IN ( SELECT C.CMMNS_CD_VALUE FROM SAC100 C, SAC110 D WHERE 1=1 AND C.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND C.CMMNS_CD_VALUE = D.CMMNS_CD_VALUE(+) AND C.USE_YN = 'Y' AND C.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD}
AND D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
)
AND (UNITY_BBSCTT_TTL_NM LIKE '%' || #{SEARCH_DATA} || '%' OR UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%')
AND UNITY_BBSCTT_TTL_NM LIKE '%'|| #{SEARCH_DATA} || '%'
AND UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%'
AND C##RG.SA_FN_GET_NAME(A.FRST_RGTR_ID) = ENC_B64(#{SEARCH_DATA})
AND UNITY_BBSCTT_TYPE_SN = #{SEARCH_DATA}
AND ENC_B64(#{SEARCH_DATA}) IN (SELECT T3.FLNM_ENCPT FROM SBA131 T1 JOIN SAA200 T2 ON T2.USER_ID = T1.FRST_RGTR_ID JOIN SCA100 T3 ON T3.ENFSN_NO = T2.ENFSN_NO WHERE T1.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO)
AND (FRST_REG_DT BETWEEN #{START_DATE} AND #{END_DATE})
AND CLLR_REG_YN = #{CLLR_REG_YN}
AND
B.UNITY_BBSCTT_ESNTAL_NO IS NULL
B.TASKWK_PRCS_SE_CD = #{arr}
AND B.TASKWK_TASKFO_SE_CD = #{TASKWK_TASKFO_SE_CD}
AND A.FRST_RGTR_ID = #{USER_ID}
AND SYSDATE - A.FRST_REG_DT > 1
ORDER BY A.FRST_REG_DT DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY
